382	                booking = _unitOfWork.Bookings.Get().Include(f => f.BookingItems).Where(f => f.Id == id && f.CustomerId == customerId).FirstOrDefault();
383	            }
384	
385	            if (booking == null)
386	            {
387	                return NotFound();
388	            }
389	
390	            // delete booking items, and update booking status
391	            for (int i = booking.BookingItems.Count - 1; i > -1; i--)
392	            {
393	                _unitOfWork.BookingItems.Delete(booking.BookingItems[i]);
394	            }
395	
396	            booking.Status = BookingStatus.Cancelled;
397	            _unitOfWork.Bookings.Update(booking);
