409	        private string calculateLocationName(int row, int column)
410	        {
411	            // columns are hexavigesimal, rows are base 10
412	            float hexvig = column + 1;
413	            var hexvigOutput = "";
414	            while (Math.Floor(hexvig) > 0)
415	            {
416	                // needed to ensure mod output is zero based
417	                hexvig -= 1;
418	                // character represented by current position ('A' dec '65')
419	                hexvigOutput = ((char)(65 + (hexvig % 26))) + hexvigOutput;
420	                // move to next position
421	                hexvig /= 26;
422	            }
423	
424	            return $"col: {hexvigOutput} - row: {row}";
425	        }
