                return NotFound();
            }

            _unitOfWork.Venues.Delete(venue);

            return Ok(venue);
        }

        [Authorize(Roles = "admin")]
        private bool VenueExists(int id)
        {
            return _unitOfWork.Venues.Exists(new Venue { Id = id });
        }
    }
}

